from web3 import Web3
import json
import os

GANACHE_URL = os.getenv("GANACHE_URL", "http://ganache:8545")

OWNER_PRIVATE_KEY = os.getenv("OWNER_PRIVATE_KEY", "0xc87509a1c067bbde78beb793e6fa76530b6382a4c0241e5e4a9ec0a0f44dc0d3")
OWNER_ADDRESS = os.getenv("OWNER_ADDRESS", "0x627306090abaB3A6e1400e9345bC60c78a8BEf57")

w3 = Web3(Web3.HTTPProvider(GANACHE_URL))

CONTRACT_ABI = json.loads('''
[{"inputs":[{"internalType":"address payable","name":"_customer","type":"address"},{"internalType":"uint256","name":"_price","type":"uint256"}],"stateMutability":"nonpayable","type":"constructor"},{"inputs":[{"internalType":"address payable","name":"_courier","type":"address"}],"name":"assignCourier","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"confirmDelivery","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"confirmDeliveryByOwner","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"courier","outputs":[{"internalType":"address payable","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"customer","outputs":[{"internalType":"address payable","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"deliveryConfirmed","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getCourier","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"isDeliveryConfirmed","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"isPaid","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"owner","outputs":[{"internalType":"address payable","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"paid","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"pay","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[],"name":"price","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"}]
''')

CONTRACT_BYTECODE = ""

def deploy_contract(customer_address, price_in_wei):
    try:
        if not w3.is_connected():
            raise ConnectionError("Unable to connect to Ganache.")
        
        customer_address = Web3.to_checksum_address(customer_address)
        owner_address = Web3.to_checksum_address(OWNER_ADDRESS)

        Contract = w3.eth.contract(abi=CONTRACT_ABI, bytecode=CONTRACT_BYTECODE)

        gas_price = w3.eth.gas_price
        if gas_price is None or gas_price == 0:
            gas_price = 1

        transaction = Contract.constructor(
            customer_address,
            price_in_wei
        ).build_transaction({
            'from': owner_address,
            'nonce': w3.eth.get_transaction_count(owner_address),
            'gas': 3000000,
            'gasPrice': gas_price
        })

        signed_txn = w3.eth.account.sign_transaction(transaction, OWNER_PRIVATE_KEY)

        tx_hash = w3.eth.send_raw_transaction(signed_txn.raw_transaction)

        tx_receipt = w3.eth.wait_for_transaction_receipt(tx_hash)

        return tx_receipt.contractAddress
    
    except Exception as e:
        print(f"Error deploying contract: {e}")
        raise

def is_valid_address(address):
    return w3.is_address(address)
